          primary: "#222222",
          secondary: "#717171",
          muted: "#B0B0B0",
        },
        surface: {
          DEFAULT: "#FFFFFF",
          muted: "#F7F7F7",
          border: "#DDDDDD",
          divider: "#EBEBEB",
        }
      },
      fontFamily: {
        cereal: ["var(--font-cereal)", "-apple-system", "BlinkMacSystemFont", "Roboto", "Helvetica Neue", "sans-serif"],
      },
      maxWidth: {
        container: "1120px",
      },
    },
  },
  plugins: [],
};

module.exports = {
  plugins: {
    tailwindcss: {},
    autoprefixer: {},
  },
};

/** @type {import('next').NextConfig} */
const nextConfig = {
  reactStrictMode: true,
  images: {
    unoptimized: true,
  },
};

module.exports = nextConfig;

"use client";

import React from "react";
import { ICONS } from "@/data/icons";

/**
 * Renders one of the authentic Airbnb SVG icons verbatim from the reference set.
 * @param {Object} props
 * @param {string} props.name Context key, e.g. "ui:share", "amen:Wifi", "hi:Self check-in"
 * @param {string} [props.className] CSS classes to apply to container
 */
export function Icon({ name, className = "w-4 h-4 inline-block" }) {
  const svg = ICONS[name];
  if (!svg) return null;
  return (
    <span
      className={className}
      aria-hidden="true"
      dangerouslySetInnerHTML={{ __html: svg }}
    />
  );
}

export default Icon;

