}

:root {
  --font-cereal: "Airbnb Cereal VF", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  --color-airbnb: #FF385C;
  --color-airbnb-dark: #E00B41;
  --color-ink-primary: #222222;
  --color-ink-secondary: #717171;
  --color-border: #DDDDDD;
  --color-divider: #EBEBEB;
  --color-bg-subtle: #F7F7F7;
}

html {
  scroll-behavior: smooth;
  color: var(--color-ink-primary);
  font-family: var(--font-cereal);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  margin: 0;
  padding: 0;
  color: #222222;
  background-color: #ffffff;
  overflow-x: hidden;
}

/* Custom scrollbar helpers */
.no-scrollbar::-webkit-scrollbar {
  display: none;
}
.no-scrollbar {
  -ms-overflow-style: none;
  scrollbar-width: none;
}

/* Screen reader only utility */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border-width: 0;
}

/* Smooth motion respecting reduced-motion preferences */
@media (prefers-reduced-motion: reduce) {
  *, ::before, ::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

