    document.body.style.overflow = "hidden";

    const handleKeyDown = (e) => {
      if (e.key === "Escape") {
        e.preventDefault();
        onClose();
      }
    };

    window.addEventListener("keydown", handleKeyDown);
    return () => {
      document.body.style.overflow = originalOverflow;
      window.removeEventListener("keydown", handleKeyDown);
    };
  }, [isOpen, onClose]);

  if (!isOpen) return null;

  const scrollToCategory = (categoryId) => {
    const el = document.getElementById(`tour-cat-${categoryId}`);
    if (el) {
      el.scrollIntoView({ behavior: "smooth", block: "start" });
    }
  };

  return (
    <div
      role="dialog"
      aria-modal="true"
      aria-label="Photo tour"
      ref={containerRef}
      className="fixed inset-0 z-50 bg-white overflow-y-auto animate-fade-in"
    >
      {/* Sticky Top Header */}
      <header className="sticky top-0 left-0 right-0 z-30 bg-white border-b border-surface-divider h-16 sm:h-20 px-6 sm:px-10 flex items-center justify-between">
        {/* Back Button */}
        <button
          type="button"
          onClick={onClose}
          aria-label="Back to listing"
          className="p-2.5 -ml-2 rounded-full hover:bg-surface-muted transition-colors text-ink-primary focus-visible:ring-2 focus-visible:ring-black"
        >
          <svg
            xmlns="http://www.w3.org/2000/svg"
            viewBox="0 0 18 18"
            className="w-4 h-4 rotate-180 fill-current"
            aria-hidden="true"
          >
            <path d="M6.7 14.7l5.3-5.3a.5.5 0 0 0 0-.8L6.7 3.3a.5.5 0 0 0-.7.7L11 9l-5 5a.5.5 0 0 0 .7.7z" />
          </svg>
        </button>

        {/* Center Heading */}
        <h1 className="text-[16px] sm:text-[18px] font-semibold text-ink-primary">
          Photo tour
        </h1>

        {/* Right Actions: Share & Save */}
        <div className="flex items-center space-x-2">
          <button
            type="button"
            aria-label="Share photo tour"
            className="p-2.5 rounded-full hover:bg-surface-muted transition-colors text-ink-primary focus-visible:ring-2 focus-visible:ring-black"
          >
            <Icon name="ui:share" className="w-4 h-4" />
          </button>
          <button
            type="button"
            aria-label="Save this listing"
            className="p-2.5 rounded-full hover:bg-surface-muted transition-colors text-ink-primary focus-visible:ring-2 focus-visible:ring-black"
          >
            <Icon name="ui:save" className="w-4 h-4" />
          </button>
        </div>
      </header>

      {/* Content Container */}
      <div className="max-w-[1240px] mx-auto px-6 sm:px-10 py-6 space-y-12">
        {/* Category Overview Thumbnail Bar */}
        <nav
          aria-label="Photo tour categories"
          className="grid grid-cols-3 sm:grid-cols-5 md:grid-cols-9 gap-3 pt-2 pb-6 border-b border-surface-divider"
        >
          {PHOTO_CATEGORIES.map((cat) => {
            const firstPhoto = cat.photos[0];
            return (
              <button
                key={cat.id}
                type="button"
                onClick={() => scrollToCategory(cat.id)}
                className="flex flex-col items-center text-center space-y-2 group focus-visible:ring-2 focus-visible:ring-black rounded-xl p-1 transition-transform hover:-translate-y-0.5"
              >
                <div className="w-full aspect-[4/3] rounded-lg overflow-hidden relative border border-surface-border bg-neutral-100">
                  {firstPhoto && (
                    <Image
                      src={`/images/${firstPhoto.file}`}
                      alt=""
                      fill
                      sizes="120px"
                      className="object-cover group-hover:scale-105 transition-transform duration-300"
                    />
                  )}
                </div>
                <span className="text-[12px] font-semibold text-ink-primary leading-tight line-clamp-2">
                  {cat.title}
                </span>
              </button>
            );
          })}
        </nav>

        {/* Categories Sections */}
        <div className="space-y-20 pb-24">
          {PHOTO_CATEGORIES.map((cat) => {
            // Group category photos into layout rows:
            // Either single full-width photo or pairs of two half-width photos
            const rows = [];
            let i = 0;
            let currentGlobalIndex = cat.startIndex;

            while (i < cat.photos.length) {
              const p = cat.photos[i];
              if (p.layout === "full") {
                rows.push({
                  type: "full",
                  photos: [{ ...p, globalIndex: currentGlobalIndex }],
                });
                currentGlobalIndex += 1;
                i += 1;
              } else {
                // half layout: take up to 2
                const pair = [{ ...p, globalIndex: currentGlobalIndex }];
                currentGlobalIndex += 1;
                i += 1;
                if (i < cat.photos.length && cat.photos[i].layout === "half") {
                  pair.push({ ...cat.photos[i], globalIndex: currentGlobalIndex });
                  currentGlobalIndex += 1;
                  i += 1;
                }
                rows.push({
                  type: "half",
                  photos: pair,
                });
              }
            }

            return (
              <section
                key={cat.id}
                id={`tour-cat-${cat.id}`}
                className="grid grid-cols-1 lg:grid-cols-12 gap-8 scroll-mt-24"
              >
                {/* Left Column: Category title & features (Sticky) */}
                <div className="lg:col-span-4 space-y-2 lg:sticky lg:top-28 self-start">
                  <h2 className="text-[26px] font-semibold text-ink-primary leading-tight">
                    {cat.title}
                  </h2>
                  {cat.features && cat.features.length > 0 && (
                    <p className="text-[14px] text-ink-secondary leading-relaxed">
                      {cat.features.join(" · ")}
                    </p>
                  )}
                </div>

                {/* Right Column: Photos Layout */}
                <div className="lg:col-span-8 space-y-3">
                  {rows.map((row, rIdx) => {
                    if (row.type === "full") {
                      const photo = row.photos[0];
                      return (
                        <div
                          key={rIdx}
                          role="button"
                          tabIndex={0}
                          onClick={() => onOpenLightbox(photo.globalIndex)}
                          onKeyDown={(e) => {
                            if (e.key === "Enter" || e.key === " ") {
                              e.preventDefault();
                              onOpenLightbox(photo.globalIndex);
                            }
                          }}
                          aria-label={`Open photo ${photo.globalIndex} of 43 in lightbox, ${photo.alt}`}
                          className="w-full aspect-[16/10.5] rounded-xl overflow-hidden relative cursor-pointer bg-neutral-100 group border border-surface-border/50 focus-visible:outline-none focus-visible:ring-4 focus-visible:ring-black"
                        >
                          <Image
                            src={`/images/${photo.file}`}
                            alt={photo.alt}
                            fill
                            sizes="(max-width: 1024px) 100vw, 760px"
                            className="object-cover group-hover:brightness-95 transition-all duration-300"
                          />
                        </div>
                      );
                    }

                    // Half layout row (1 or 2 photos)
                    return (
                      <div key={rIdx} className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                        {row.photos.map((photo) => (
                          <div
                            key={photo.globalIndex}
                            role="button"
                            tabIndex={0}
                            onClick={() => onOpenLightbox(photo.globalIndex)}
                            onKeyDown={(e) => {
                              if (e.key === "Enter" || e.key === " ") {
                                e.preventDefault();
                                onOpenLightbox(photo.globalIndex);
                              }
                            }}
                            aria-label={`Open photo ${photo.globalIndex} of 43 in lightbox, ${photo.alt}`}
                            className="w-full aspect-[16/10.5] rounded-xl overflow-hidden relative cursor-pointer bg-neutral-100 group border border-surface-border/50 focus-visible:outline-none focus-visible:ring-4 focus-visible:ring-black"
                          >
                            <Image
                              src={`/images/${photo.file}`}
                              alt={photo.alt}
                              fill
                              sizes="(max-width: 640px) 100vw, 380px"
                              className="object-cover group-hover:brightness-95 transition-all duration-300"
                            />
                          </div>
                        ))}
                      </div>
                    );
                  })}
                </div>
              </section>
            );
          })}
        </div>
      </div>
    </div>
  );
}

export default PhotoTour;

"use client";

import React, { useEffect, useCallback, useRef } from "react";
import Image from "next/image";
import { Icon } from "@/components/common/Icon";
import { ALL_PHOTOS } from "@/data/photos";

export function Lightbox({
  isOpen,
  currentPhotoIndex = 1,
  onClose,
  onNavigate,
  onReturnToGrid,
}) {
  const totalPhotos = ALL_PHOTOS.length;
  const currentPhoto = ALL_PHOTOS.find((p) => p.index === currentPhotoIndex) || ALL_PHOTOS[0];

  const handlePrev = useCallback(() => {
    if (currentPhotoIndex > 1) {
      onNavigate(currentPhotoIndex - 1);
    }
  }, [currentPhotoIndex, onNavigate]);

  const handleNext = useCallback(() => {
    if (currentPhotoIndex < totalPhotos) {
      onNavigate(currentPhotoIndex + 1);
    }
  }, [currentPhotoIndex, totalPhotos, onNavigate]);

  // Keyboard navigation
  useEffect(() => {
    if (!isOpen) return;

    const originalOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";

    const handleKeyDown = (e) => {
      if (e.key === "Escape") {
        e.preventDefault();
        e.stopPropagation();
        onClose();
      } else if (e.key === "ArrowLeft") {
        e.preventDefault();
        handlePrev();
      } else if (e.key === "ArrowRight") {
        e.preventDefault();
        handleNext();
      }
    };

    window.addEventListener("keydown", handleKeyDown);
    return () => {
      document.body.style.overflow = originalOverflow;
      window.removeEventListener("keydown", handleKeyDown);
    };
  }, [isOpen, onClose, handlePrev, handleNext]);

  if (!isOpen || !currentPhoto) return null;

  return (
    <div
      role="dialog"
      aria-modal="true"
      aria-label={`Photo viewer: ${currentPhoto.categoryTitle}, image ${currentPhoto.index} of ${totalPhotos}`}
      className="fixed inset-0 z-50 bg-white flex flex-col select-none animate-fade-in"
    >
      {/* Top Navigation Bar */}
      <header className="h-16 sm:h-20 px-6 sm:px-10 flex items-center justify-between border-b border-surface-divider/40 flex-shrink-0 bg-white z-10">
        {/* Top-Left: Grid Icon (Return to Photo Tour) */}
        <div>
          <button
            type="button"
            onClick={onReturnToGrid || onClose}
            aria-label="Return to photo tour overview"
            className="p-2.5 -ml-2 rounded-full hover:bg-surface-muted transition-colors text-ink-primary focus-visible:ring-2 focus-visible:ring-black"
          >
            <Icon name="ui:lbGrid" className="w-5 h-5 text-ink-primary" />
          </button>
        </div>

        {/* Top-Center: Category Title */}
        <div className="text-[16px] font-semibold text-ink-primary">
          {currentPhoto.categoryTitle}
        </div>

        {/* Top-Right: Counter and Close */}
        <div className="flex items-center space-x-4">
          <span className="text-[14px] font-medium text-ink-primary">
            {currentPhoto.index} of {totalPhotos}
          </span>

          <button
            type="button"
            onClick={onClose}
            aria-label="Close photo viewer"
            className="p-2.5 rounded-full hover:bg-surface-muted transition-colors text-ink-primary focus-visible:ring-2 focus-visible:ring-black"
          >
            <svg
              xmlns="http://www.w3.org/2000/svg"
              viewBox="0 0 32 32"
              className="w-4 h-4 fill-current stroke-current stroke-2"
            >
              <path d="M26.29 4.29L16 14.59 5.71 4.29 4.29 5.71 14.59 16 4.29 26.29 5.71 27.71 16 17.41 26.29 27.71 27.71 26.29 17.41 16 27.71 5.71z" />
            </svg>
          </button>
        </div>
      </header>

      {/* Main Image Stage */}
      <div className="flex-1 relative flex items-center justify-center p-4 sm:p-8 overflow-hidden">
        {/* Previous Button (Left) */}
        <div className="absolute left-4 sm:left-10 z-20">
          <button
            type="button"
            onClick={handlePrev}
            disabled={currentPhotoIndex <= 1}
            aria-label="Previous photo"
            className={`w-12 h-12 rounded-full border border-surface-border bg-white shadow-md flex items-center justify-center transition-all ${
              currentPhotoIndex <= 1
                ? "opacity-25 cursor-not-allowed border-surface-divider"
                : "hover:scale-105 hover:border-black text-ink-primary focus-visible:ring-2 focus-visible:ring-black active:scale-95"
            }`}
          >
            <svg
              xmlns="http://www.w3.org/2000/svg"
              viewBox="0 0 18 18"
              className="w-4 h-4 rotate-180 fill-current"
              aria-hidden="true"
            >
              <path d="M6.7 14.7l5.3-5.3a.5.5 0 0 0 0-.8L6.7 3.3a.5.5 0 0 0-.7.7L11 9l-5 5a.5.5 0 0 0 .7.7z" />
            </svg>
          </button>
        </div>

        {/* Centered Large Image */}
        <div className="relative w-full h-full max-h-[82vh] max-w-[85vw] flex items-center justify-center">
          <div className="relative w-full h-full">
            <Image
              key={currentPhoto.src}
              src={currentPhoto.src}
              alt={currentPhoto.alt}
              fill
              priority
              sizes="85vw"
              className="object-contain transition-opacity duration-200"
            />
          </div>
        </div>

        {/* Next Button (Right) */}
        <div className="absolute right-4 sm:right-10 z-20">
          <button
            type="button"
            onClick={handleNext}
            disabled={currentPhotoIndex >= totalPhotos}
            aria-label="Next photo"
            className={`w-12 h-12 rounded-full border border-surface-border bg-white shadow-md flex items-center justify-center transition-all ${
              currentPhotoIndex >= totalPhotos
                ? "opacity-25 cursor-not-allowed border-surface-divider"
                : "hover:scale-105 hover:border-black text-ink-primary focus-visible:ring-2 focus-visible:ring-black active:scale-95"
            }`}
          >
            <svg
              xmlns="http://www.w3.org/2000/svg"
              viewBox="0 0 18 18"
              className="w-4 h-4 fill-current"
              aria-hidden="true"
            >
              <path d="M6.7 14.7l5.3-5.3a.5.5 0 0 0 0-.8L6.7 3.3a.5.5 0 0 0-.7.7L11 9l-5 5a.5.5 0 0 0 .7.7z" />
            </svg>
          </button>
        </div>
      </div>
    </div>
  );
}

export default Lightbox;

"use client";

import React, { useState, useEffect, useCallback, Suspense } from "react";
import Header from "@/components/layout/Header";
import StickySubNav from "@/components/layout/StickySubNav";
import ListingHeader from "@/components/listing/ListingHeader";
import HeroGallery from "@/components/listing/HeroGallery";
import ListingSummary from "@/components/listing/ListingSummary";
import HighlightsSection from "@/components/listing/HighlightsSection";
import DescriptionSection from "@/components/listing/DescriptionSection";
import SleepSection from "@/components/listing/SleepSection";
import AmenitiesSection from "@/components/listing/AmenitiesSection";
import CalendarSection from "@/components/listing/CalendarSection";
import ReviewsSection from "@/components/listing/ReviewsSection";
import LocationSection from "@/components/listing/LocationSection";
import HostSection from "@/components/listing/HostSection";
import ThingsToKnow from "@/components/listing/ThingsToKnow";
import NearbyStays from "@/components/listing/NearbyStays";
import Footer from "@/components/layout/Footer";
import StickyBookingCard from "@/components/booking/StickyBookingCard";
import PhotoTour from "@/components/photoTour/PhotoTour";
import Lightbox from "@/components/lightbox/Lightbox";

import { LISTING_DATA } from "@/data/listing";
import { REVIEWS_DATA } from "@/data/reviews";
import { NEARBY_STAYS } from "@/data/nearbyStays";
import { ALL_PHOTOS } from "@/data/photos";

function ListingApp() {
  // Navigation views: 'listing' | 'photos' | 'lightbox'
  const [currentView, setCurrentView] = useState("listing");
  const [activePhotoIndex, setActivePhotoIndex] = useState(1);

  // Date selection state (shared between calendar & booking card)
  const [startDate, setStartDate] = useState(LISTING_DATA.defaultStartDate);
  const [endDate, setEndDate] = useState(LISTING_DATA.defaultEndDate);

  // Synchronize with URL query params and browser history
  const updateUrl = useCallback((view, photoIdx) => {
    if (typeof window === "undefined") return;
    const url = new URL(window.location.href);

    if (view === "listing") {
      url.searchParams.delete("view");
      url.searchParams.delete("photo");
    } else if (view === "photos") {
      url.searchParams.set("view", "photos");
      url.searchParams.delete("photo");
    } else if (view === "lightbox") {
      url.searchParams.set("view", "photos");
      url.searchParams.set("photo", String(photoIdx || 1));
    }

    window.history.pushState({ view, photoIdx }, "", url.toString());
  }, []);

  // Handle browser back/forward buttons
  useEffect(() => {
    const handlePopState = (e) => {
      const state = e.state;
      if (!state || !state.view || state.view === "listing") {
        setCurrentView("listing");
      } else if (state.view === "photos") {
        setCurrentView("photos");
      } else if (state.view === "lightbox") {
        setCurrentView("lightbox");
        setActivePhotoIndex(state.photoIdx || 1);
      } else {
        // Parse from URL directly if state is empty
        const params = new URLSearchParams(window.location.search);
        const viewParam = params.get("view");
        const photoParam = params.get("photo");
        if (viewParam === "photos") {
          if (photoParam) {
            setCurrentView("lightbox");
            setActivePhotoIndex(Number(photoParam) || 1);
          } else {
            setCurrentView("photos");
          }
        } else {
          setCurrentView("listing");
        }
      }
    };

    // Initial check on mount
    const params = new URLSearchParams(window.location.search);
    const v = params.get("view");
    const p = params.get("photo");
    if (v === "photos") {
      if (p) {
        setCurrentView("lightbox");
        setActivePhotoIndex(Number(p) || 1);
      } else {
        setCurrentView("photos");
      }
    }

    window.addEventListener("popstate", handlePopState);
    return () => window.removeEventListener("popstate", handlePopState);
  }, []);

  // View transition handlers
  const openPhotoTour = (photoIndex = 1) => {
    setCurrentView("photos");
    setActivePhotoIndex(photoIndex);
    updateUrl("photos");
  };

  const closePhotoTour = () => {
    setCurrentView("listing");
    updateUrl("listing");
  };

  const openLightbox = (photoIndex) => {
    setActivePhotoIndex(photoIndex);
    setCurrentView("lightbox");
    updateUrl("lightbox", photoIndex);
  };

  const closeLightbox = () => {
    // Escape from lightbox returns to Photo Tour!
    setCurrentView("photos");
    updateUrl("photos");
  };

  const navigateLightbox = (nextIndex) => {
    setActivePhotoIndex(nextIndex);
    updateUrl("lightbox", nextIndex);
  };

  // Scroll to calendar when booking date box is clicked
  const handleDateBoxClick = () => {
    const el = document.getElementById("amenities"); // scroll to calendar region
    if (el) {
      el.scrollIntoView({ behavior: "smooth" });
    }
  };

  const handleDateChange = (start, end) => {
    setStartDate(start);
    setEndDate(end);
  };

  // Calculate dynamic price for StickySubNav
  const calculateTotalNights = () => {
    if (!startDate || !endDate) return 5;
    const s = new Date(startDate);
    const e = new Date(endDate);
    const diff = Math.round((e - s) / (1000 * 60 * 60 * 24));
    return diff > 0 ? diff : 5;
  };

  const dynamicNights = calculateTotalNights();
  const dynamicTotalFormatted =
    "₹" + (dynamicNights * LISTING_DATA.pricePerNight).toLocaleString("en-IN");

  return (
    <main className="min-h-screen bg-white text-ink-primary font-cereal">
      {/* Top Main Navigation Header */}
      <Header onSearchClick={handleDateBoxClick} />

      {/* Sticky Secondary Navigation (appears on scroll) */}
      <StickySubNav
        price={dynamicTotalFormatted}
        nights={dynamicNights}
        rating={LISTING_DATA.rating}
        reviews={LISTING_DATA.reviewCount}
        onReserveClick={() => {
          window.scrollTo({ top: 1200, behavior: "smooth" });
        }}
      />

      {/* Main Listing Content Container (max 1120px width) */}
      <div className="max-w-container mx-auto px-6 xl:px-0">
        {/* Listing Title, Share & Save */}
        <ListingHeader title={LISTING_DATA.title} />

        {/* Hero Gallery Mosaic */}
        <HeroGallery
          images={LISTING_DATA.heroImages}
          onOpenPhotoTour={openPhotoTour}
        />

        {/* 2-Column Content Layout: Left Details, Right Sticky Booking Card */}
        <div className="flex flex-col lg:flex-row gap-12 lg:gap-16 pt-8 relative">
          {/* Left Column (Details, sections, reviews, host) */}
          <div className="flex-1 min-w-0">
            {/* Listing Summary: Room stats, Guest favourite, Host */}
            <ListingSummary
              propertyType={LISTING_DATA.propertyType}
              location={LISTING_DATA.location}
              guests={LISTING_DATA.guests}
              bedrooms={LISTING_DATA.bedrooms}
              beds={LISTING_DATA.beds}
              bathrooms={LISTING_DATA.bathrooms}
              rating={LISTING_DATA.rating}
              reviewCount={LISTING_DATA.reviewCount}
              host={LISTING_DATA.host}
            />

            {/* Property Highlights */}
            <HighlightsSection highlights={LISTING_DATA.highlights} />

            {/* Description */}
            <DescriptionSection description={LISTING_DATA.description} />

            {/* Where you'll sleep */}
            <SleepSection
              sleepingArrangements={LISTING_DATA.sleepingArrangements}
              onOpenPhotoTour={openPhotoTour}
            />

            {/* Amenities Grid & Modal */}
            <AmenitiesSection
              amenitiesSummary={LISTING_DATA.amenitiesSummary}
              fullAmenities={LISTING_DATA.fullAmenities}
            />

            {/* Interactive Calendar Section */}
            <CalendarSection
              startDate={startDate}
              endDate={endDate}
              onDateChange={handleDateChange}
              location="Candolim"
            />
          </div>

          {/* Right Column: Sticky Booking Card & Promo */}
          <StickyBookingCard
            pricePerNight={LISTING_DATA.pricePerNight}
            startDate={startDate}
            endDate={endDate}
            onDateBoxClick={handleDateBoxClick}
          />
        </div>

        {/* Full-width Sections below fold */}
        {/* Reviews Section */}
        <ReviewsSection reviewsData={REVIEWS_DATA} />

        {/* Location Section */}
        <LocationSection />

        {/* Meet Your Host Section */}
        <HostSection host={LISTING_DATA.host} />

        {/* Things to Know */}
        <ThingsToKnow thingsToKnow={LISTING_DATA.thingsToKnow} />

        {/* More Stays Nearby Carousel */}
        <NearbyStays stays={NEARBY_STAYS} />
      </div>

      {/* Global Footer */}
      <Footer />

      {/* VIEW 2: Photo Tour Fullscreen View */}
      <PhotoTour
        isOpen={currentView === "photos"}
        onClose={closePhotoTour}
        onOpenLightbox={openLightbox}
      />

      {/* VIEW 3: Lightbox View */}
      <Lightbox
        isOpen={currentView === "lightbox"}
        currentPhotoIndex={activePhotoIndex}
        onClose={closeLightbox}
        onNavigate={navigateLightbox}
        onReturnToGrid={() => {
          setCurrentView("photos");
          updateUrl("photos");
        }}
      />
    </main>
  );
}

export default function Home() {
  return (
    <Suspense fallback={<div className="min-h-screen bg-white" />}>
      <ListingApp />
    </Suspense>
  );
}

