async () => {
  const report = {};

  // 1. Test Listing Page: Hero & Show All Photos
  const showAllBtn = Array.from(document.querySelectorAll('button')).find(b => b.textContent.includes('Show all photos'));
  report.showAllBtnPresent = !!showAllBtn;
  if (showAllBtn) {
    showAllBtn.click();
    await new Promise(r => setTimeout(r, 200));
    report.tourOpenedFromShowAll = window.location.search.includes('view=photos');

    // Test Escape to close
    window.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true }));
    await new Promise(r => setTimeout(r, 200));
    report.tourClosedFromEscape = !window.location.search.includes('view=photos');
  }

  // 2. Test Amenities Modal
  const showAmenitiesBtn = Array.from(document.querySelectorAll('button')).find(b => b.textContent.includes('Show all 50 amenities'));
  report.showAmenitiesBtnPresent = !!showAmenitiesBtn;
  if (showAmenitiesBtn) {
    showAmenitiesBtn.click();
    await new Promise(r => setTimeout(r, 200));
    report.amenityModalOpened = !!document.getElementById('amenities-modal-title');
    report.amenityModalOverflowLocked = document.body.style.overflow === 'hidden';

    // Close modal via Escape
    window.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true }));
    await new Promise(r => setTimeout(r, 200));
    report.amenityModalClosed = !document.getElementById('amenities-modal-title');
  }

  // 3. Test Reviews Modal
  const showReviewsBtn = Array.from(document.querySelectorAll('button')).find(b => b.textContent.includes('Show all 19 reviews'));
  report.showReviewsBtnPresent = !!showReviewsBtn;
  if (showReviewsBtn) {
    showReviewsBtn.click();
    await new Promise(r => setTimeout(r, 200));
    report.reviewModalOpened = !!document.querySelector('input[placeholder="Search reviews"]');

    // Close modal via Escape
    window.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true }));
    await new Promise(r => setTimeout(r, 200));
    report.reviewModalClosed = !document.querySelector('input[placeholder="Search reviews"]');
  }

  // 4. Test Nearby Stays Pagination
  const nextStayBtn = document.querySelector('button[aria-label="Next stays"]');
  const prevStayBtn = document.querySelector('button[aria-label="Previous stays"]');
  report.nearbyPaginationPresent = !!(nextStayBtn && prevStayBtn);
  if (nextStayBtn) {
    nextStayBtn.click();
    await new Promise(r => setTimeout(r, 100));
    report.nearbyPage2Reached = document.body.textContent.includes('2 / 2');
    if (prevStayBtn) {
      prevStayBtn.click();
      await new Promise(r => setTimeout(r, 100));
      report.nearbyPage1Restored = document.body.textContent.includes('1 / 2');
    }
  }

  return report;
}

