    // Click plus adult to reach max limit
    if (plusAdultBtn) {
      plusAdultBtn.click();
      await new Promise(r => setTimeout(r, 100));
      // Total guests is now 3 (the max)
      // plusAdultBtn should now be disabled
      report.plusAdultDisabledAtMax = plusAdultBtn.disabled;
