    // Close guest selector
    const closeBtn = Array.from(document.querySelectorAll('button')).find(b => b.textContent.trim() === 'Close');
    if (closeBtn) {
      closeBtn.click();
      await new Promise(r => setTimeout(r, 100));
      report.guestSelectorClosed = !document.querySelector('[role="dialog"][aria-label="Guest selection"]');
    }
  }

  return report;
}

