() => {
  const pill = document.querySelector('div[role="button"][aria-label="Search destinations, dates, and guests"]');
  if (!pill) return { error: "Pill not found" };
  const pillRect = pill.getBoundingClientRect();
  const children = Array.from(pill.children).map((child, i) => {
    const r = child.getBoundingClientRect();
    return {
      index: i,
      tagName: child.tagName,
      className: child.className,
      rect: { left: r.left, right: r.right, top: r.top, bottom: r.bottom, width: r.width, height: r.height },
      overflowRight: r.right - pillRect.right,
      overflowLeft: pillRect.left - r.left,
      innerHTML: child.innerHTML.slice(0, 100)
    };
  });

  const searchBtn = pill.querySelector('button[aria-label="Search"]');
  let btnRect = null;
  let btnOverflow = null;
  if (searchBtn) {
    const br = searchBtn.getBoundingClientRect();
    btnRect = { left: br.left, right: br.right, width: br.width, height: br.height };
    btnOverflow = br.right - pillRect.right;
  }

  return {
    pillRect: { left: pillRect.left, right: pillRect.right, width: pillRect.width, height: pillRect.height },
    children,
    searchBtn: { btnRect, btnOverflow }
  };
}

