async () => {
  const results = {};

  // 1. Listing View Verification
  results.hasHeader = !!document.querySelector('header');
  results.hasHero = !!document.getElementById('photos');
  results.hasAmenities = !!document.getElementById('amenities');
  results.hasReviews = !!document.getElementById('reviews');
  results.hasCalendar = !!document.querySelector('[aria-label="Previous month"]');
  results.hasBookingCard = !!document.querySelector('aside[aria-label="Reservation details"]');
  results.hasNearby = !!document.querySelector('[aria-label="Scrollable list of nearby stays"]');

  // 2. Open Photo Tour
  const showAllPhotosBtn = Array.from(document.querySelectorAll('button')).find(b => b.textContent.includes('Show all photos'));
  showAllPhotosBtn.click();
  await new Promise(r => setTimeout(r, 350));

  const photoTourDialog = document.querySelector('[role="dialog"][aria-label="Photo tour"]');
  results.photoTourOpens = !!photoTourDialog;
  results.photoTourCategories = document.querySelectorAll('[aria-label="Photo tour categories"] button').length;

  // 3. Open Lightbox from Photo Tour
  const photoButtons = Array.from(document.querySelectorAll('[role="dialog"][aria-label="Photo tour"] [role="button"]'));
  results.totalPhotosInTour = photoButtons.length;
  // Click first photo
  photoButtons[0]?.click();
  await new Promise(r => setTimeout(r, 300));

  const lightbox = document.querySelector('[role="dialog"][aria-label*="Photo viewer"]');
  results.lightboxOpens = !!lightbox;
  results.lightboxCounter = lightbox?.querySelector('span.text-\\[14px\\]')?.textContent?.trim();

  // 4. Keyboard Navigation: ArrowRight
  window.dispatchEvent(new KeyboardEvent('keydown', { key: 'ArrowRight', bubbles: true }));
  await new Promise(r => setTimeout(r, 100));
  results.afterArrowRightCounter = lightbox?.querySelector('span.text-\\[14px\\]')?.textContent?.trim();

  // 5. Keyboard Navigation: Escape (returns to photo tour)
  window.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true }));
  await new Promise(r => setTimeout(r, 300));
  results.afterEscapeLightboxInDOM = !!document.querySelector('[role="dialog"][aria-label*="Photo viewer"]');
  results.afterEscapeTourStillInDOM = !!document.querySelector('[role="dialog"][aria-label="Photo tour"]');

  // 6. Escape from photo tour (returns to listing)
  window.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true }));
  await new Promise(r => setTimeout(r, 350));
  results.afterSecondEscapeTourInDOM = !!document.querySelector('[role="dialog"][aria-label="Photo tour"]');

  // 7. Test Amenities Modal
  const amenBtn = Array.from(document.querySelectorAll('button')).find(b => b.textContent.includes('Show all') && b.textContent.includes('amenities'));
  amenBtn.click();
  await new Promise(r => setTimeout(r, 350));

  const amenDialog = document.querySelector('[role="dialog"][aria-labelledby="amenities-modal-title"]');
  results.amenitiesModalOpens = !!amenDialog;
  results.amenitiesBodyScrollLocked = document.body.style.overflow === 'hidden';

  // Escape to close
  window.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true }));
  await new Promise(r => setTimeout(r, 350));
  results.amenitiesModalClosed = !document.querySelector('[role="dialog"][aria-labelledby="amenities-modal-title"]');
  results.amenitiesBodyScrollRestored = document.body.style.overflow !== 'hidden';

  return results;
}

